// Unit wording from the pinned PyBot maths facts table.
pattern!(HEAVY, r###"\A(?:(?:how (?:heavy|much) (?:is|does|do|are)|what (?:does|is)|how much does)\s+(?:a |an |one |1 )?([a-z']+?)\s*(?:weigh(?:s)?|weigh in at|in weight)?\s*(?:in kilos|in kg|in pounds|in pounds and ounces|in lbs)?)\z"###);
pattern!(HOW_MUCH, r###"\A(?:how much (?:is |are )?(?:a |an |one |1 )?([a-z']+)(?: of [a-z]+)? (?:in|to) (?:a |an |one |1 )?([a-z']+)(?: of .*)?)\z"###);
pattern!(AMOUNT, r###"\A(?:(?:how many|number of)\s+([a-z']+)\s+(.*))\z"###);
pattern!(POLITE, r###"^(?:(?:ok|okay|so|and|but|right|hi|hey|please|sorry|quick one|quick question|can you tell me|do you know|tell me|just wondering|i was wondering|wondering|out of interest)\b[\s]+)+"###);
pattern!(FILLER, r###"\b(?:please|for me|thanks|thank you|exactly|roughly|about|approximately|again|then|altogether|in total|by the way|actually)\b"###);
